steps.script:
if HandoffManager._visible:
	HandoffManager._on_ready_pressed()
return HandoffManager._visible

var m = tree.root.get_node("Main")
var br = m.get_node("BoardRoot")
var old = br.get_node_or_null("T12Probe")
if old != null:
	br.remove_child(old)
	old.free()
var probe = Node2D.new()
probe.name = "T12Probe"
br.add_child(probe)
var dfb = br.get_node("DamageFeedbackVisual")
var r32 = Measurement.base_radius_px(32)
var r40 = Measurement.base_radius_px(40)
# MovementRangeVisual (BoardRoot node, T28): Kaptin Badrukk's M disc + a 12" weapon ring
var mrv = br.get_node("MovementRangeVisual")
mrv.set_from("U_KAPTIN_BADRUKK_A", 12.0)
# MovementRangeVisual.DragRuler (MovementController, T03): green / yellow / red runs, a waypoint, the label
var dr = load("res://scripts/MovementRangeVisual.gd").DragRuler.new()
dr.name = "DragRuler"
probe.add_child(dr)
dr.show_path([{"from": Vector2(105, 330), "to": Vector2(150, 285), "color_slot": "CONFIRMED_GREEN", "distance_inches": 1.6}, {"from": Vector2(150, 285), "to": Vector2(205, 250), "color_slot": "MARGINAL_YELLOW", "distance_inches": 1.6}, {"from": Vector2(205, 250), "to": Vector2(250, 225), "color_slot": "INVALID_RED", "distance_inches": 1.3}], [Vector2(150, 285)], Vector2(250, 225), "13.4\"", "INVALID_RED", r40)
# CoherencyCircleVisual (DeploymentController): in coherency (green) and out of it (red)
var CCV = load("res://scripts/CoherencyCircleVisual.gd")
var cc_in = CCV.new()
cc_in.name = "CoherencyIn"
cc_in.position = Vector2(380, 1900)
probe.add_child(cc_in)
cc_in.setup(r32)
cc_in.set_in_range(true)
var cc_out = CCV.new()
cc_out.name = "CoherencyOut"
cc_out.position = Vector2(200, 1700)
probe.add_child(cc_out)
cc_out.setup(r32)
cc_out.set_in_range(false)
# ChargeTrajectoryPreview (ChargeController target selection): easy / average / hard minimum rolls
var CTP = load("res://scripts/ChargeTrajectoryPreview.gd")
var t_easy = CTP.new()
probe.add_child(t_easy)
t_easy.name = "TrajectoryEasy"
t_easy.update_trajectories([{"from": Vector2(320, 410), "to": Vector2(360, 330), "distance_inches": 1.7}], 1.7, Vector2(300, 440))
var t_mid = CTP.new()
probe.add_child(t_mid)
t_mid.name = "TrajectoryMid"
t_mid.update_trajectories([{"from": Vector2(760, 1700), "to": Vector2(860, 1620), "distance_inches": 7.5}], 7.5, Vector2(760, 1740))
var t_hard = CTP.new()
probe.add_child(t_hard)
t_hard.name = "TrajectoryHard"
t_hard.update_trajectories([{"from": Vector2(1000, 1700), "to": Vector2(1100, 1620), "distance_inches": 10.2}], 10.2, Vector2(1000, 1740))
# HumanMovementPathVisual (MovementController drag-to-plan): one path within the move cap, one past it
var HMP = load("res://scripts/HumanMovementPathVisual.gd")
var hp = HMP.new()
hp.name = "HumanPlan"
probe.add_child(hp)
hp.update_planning_paths([{"from": Vector2(140, 420), "to": Vector2(215, 350), "distance": 2.6}, {"from": Vector2(100, 1820), "to": Vector2(230, 1770), "distance": 3.3}], 1, 3.0)
# DeepStrikeExclusionVisual (Main, reserves arrival): the bubble around every bottom-half P2 model
var DSE = load("res://scripts/DeepStrikeExclusionVisual.gd")
var dse = DSE.new()
dse.name = "DeepStrike"
probe.add_child(dse)
var enemies = []
for uid in GameState.state.units:
	var u = GameState.state.units[uid]
	if int(u.get("owner", 0)) != 2:
		continue
	for md in u.get("models", []):
		var p = md.get("position", null)
		if md.get("alive", true) and typeof(p) == TYPE_DICTIONARY and float(p.get("y", 0.0)) > 1200.0:
			enemies.append({"x": float(p.x), "y": float(p.y), "base_mm": int(md.get("base_mm", 32))})
dse.show_exclusion(enemies)
# InfiltratorExclusionVisual (DeploymentController): P1's stand-off line around the enemy (P2) zone
var IEV = load("res://scripts/InfiltratorExclusionVisual.gd")
var iev = IEV.new()
iev.name = "Infiltrator"
probe.add_child(iev)
iev.show_exclusion(GameState.get_enemy_deployment_zone(1).get("poly", []))
var still = [probe, dfb, mrv, m.p1_zone, m.p2_zone]
for n in still:
	n.process_mode = Node.PROCESS_MODE_DISABLED
var anim = [m.p1_zone, m.p2_zone]
anim.append_array(probe.get_children())
for n in anim:
	if "_pulse_time" in n:
		n._pulse_time = 0.0
	if "_march_offset" in n:
		n._march_offset = 0.0
	n.queue_redraw()
dfb.queue_redraw()
return probe.get_child_count()

var m = tree.root.get_node("Main")
var br = m.get_node("BoardRoot")
var probe = br.get_node("T12Probe")
var dfb = br.get_node("DamageFeedbackVisual")
var mrv = br.get_node("MovementRangeVisual")
seed(1212)
var r40 = Measurement.base_radius_px(40)
# ChargeArrowVisual (ChargeController declaration): rolled success, rolled failure, declared (no roll yet)
var CAV = load("res://scripts/ChargeArrowVisual.gd")
var a_ok = CAV.new()
a_ok.name = "ArrowSuccess"
probe.add_child(a_ok)
a_ok.show_static(Vector2(400, 250), Vector2(503, 100))
a_ok.set_roll_result(9, true)
var a_bad = CAV.new()
a_bad.name = "ArrowFail"
probe.add_child(a_bad)
a_bad.show_static(Vector2(480, 1600), Vector2(640, 1615))
a_bad.set_roll_result(4, false)
var a_dec = CAV.new()
a_dec.name = "ArrowDeclared"
probe.add_child(a_dec)
a_dec.show_static(Vector2(480, 1690), Vector2(640, 1700))
# AIMovementPathVisual (Main / AIPlayer after an AI move): a P2 trail and a P1 trail
var AIP = load("res://scripts/AIMovementPathVisual.gd")
var ai2 = AIP.new()
ai2.name = "AIPathP2"
probe.add_child(ai2)
ai2.show_paths([{"from": Vector2(900, 1810), "to": Vector2(800, 1770)}, {"from": Vector2(1160, 1810), "to": Vector2(1070, 1775)}], 2)
var ai1 = AIP.new()
ai1.name = "AIPathP1"
probe.add_child(ai1)
ai1.show_paths([{"from": Vector2(560, 20), "to": Vector2(650, 60)}], 1)
# DamageFeedbackVisual (BoardRoot node, T34): hit flash, death ring + debris + skull, damage / kill
# numbers, the kill notification and the AI result summary
dfb.play_damage_flash(Vector2(503, 100), r40, 2, 3)
dfb.play_death_animation(Vector2(440, 100), r40)
dfb.play_floating_number(Vector2(503, 60), 3, false)
dfb.play_floating_number(Vector2(440, 60), 2, true)
dfb.play_kill_notification(Vector2(300, 168), "Custodian Guard")
dfb.play_result_summary(Vector2(250, 30), "2 hits, 1 wound")
var still = [probe, dfb, mrv, m.p1_zone, m.p2_zone]
for n in still:
	n.process_mode = Node.PROCESS_MODE_DISABLED
var anim = [m.p1_zone, m.p2_zone]
anim.append_array(probe.get_children())
for n in anim:
	if "_pulse_time" in n:
		n._pulse_time = 0.0
	if "_march_offset" in n:
		n._march_offset = 0.0
	n.queue_redraw()
dfb.queue_redraw()
for e in dfb._effects:
	e.elapsed = 0.12 if e.type == "damage_flash" else 0.25
for c in dfb.get_children():
	if c is Label and c.z_index == 56:
		var sc = c.get_theme_color("font_color")
		sc.a = 1.0
		c.add_theme_color_override("font_color", sc)
dfb.queue_redraw()
return probe.get_child_count()

var dfb = tree.root.get_node("Main/BoardRoot/DamageFeedbackVisual")
var n = 0
for c in dfb.get_children():
	if c is Label or c is ColorRect:
		n += 1
return "%d effects, %d labels/backdrops" % [dfb._effects.size(), n]

var names = ["MovementRangeVisual", "EngagementRangeVisual", "CoherencyCircleVisual", "ChargeTrajectoryPreview", "DeepStrikeExclusionVisual", "DamageFeedbackVisual", "ChargeArrowVisual", "DeploymentZoneVisual", "AIMovementPathVisual", "HumanMovementPathVisual", "InfiltratorExclusionVisual"]
var classes = []
for n in names:
	classes.append([n, load("res://scripts/%s.gd" % n)])
classes.append(["MovementRangeVisual.DragRuler", load("res://scripts/MovementRangeVisual.gd").DragRuler])
var checked = 0
var bad = []
for pair in classes:
	var s = pair[1]
	var cm = s.get_script_constant_map()
	for k in cm:
		if typeof(cm[k]) == TYPE_COLOR:
			checked += 1
			if UIConstants.slot_name(cm[k]) == "" and UIConstants.chrome_name(cm[k]) == "":
				bad.append("%s.%s=#%s" % [pair[0], k, cm[k].to_html()])
	var inst = s.new()
	for prop in inst.get_property_list():
		if prop.type == TYPE_COLOR and (prop.usage & PROPERTY_USAGE_SCRIPT_VARIABLE):
			checked += 1
			var v = inst.get(prop.name)
			if UIConstants.slot_name(v) == "" and UIConstants.chrome_name(v) == "":
				bad.append("%s.%s=#%s" % [pair[0], prop.name, v.to_html()])
	inst.free()
return "%d colours, offenders: [%s]" % [checked, ", ".join(bad)]

var expect = {
	"ChargeArrowVisual": {"ARROW_COLOR": "WARNING_ORANGE", "ARROW_SUCCESS_COLOR": "CONFIRMED_GREEN", "ARROW_FAIL_COLOR": "INVALID_RED", "CHARGE_FLASH_COLOR": "WARNING_ORANGE", "PENDING_TEXT_COLOR": "MARGINAL_YELLOW"},
	"ChargeTrajectoryPreview": {"TRAJECTORY_COLOR": "WARNING_ORANGE", "SUMMARY_GOOD_COLOR": "CONFIRMED_GREEN", "SUMMARY_MID_COLOR": "MARGINAL_YELLOW", "SUMMARY_HARD_COLOR": "INVALID_RED"},
	"AIMovementPathVisual": {"P1_TRAIL_COLOR": "FRIENDLY_PLAYER_TEAL", "P2_TRAIL_COLOR": "ENEMY_PLAYER_MAGENTA"},
	"HumanMovementPathVisual": {"P1_TRAIL_COLOR": "FRIENDLY_PLAYER_TEAL", "P2_TRAIL_COLOR": "ENEMY_PLAYER_MAGENTA", "OVER_CAP_COLOR": "INVALID_RED"},
	"CoherencyCircleVisual": {"COLOR_GREEN": "CONFIRMED_GREEN", "COLOR_RED": "INVALID_RED"},
	"DeepStrikeExclusionVisual": {"LINE_COLOR": "INVALID_RED", "GLOW_COLOR": "INVALID_RED", "FILL_COLOR": "INVALID_RED"},
	"InfiltratorExclusionVisual": {"LINE_COLOR": "INVALID_RED", "GLOW_COLOR": "INVALID_RED"},
	"DamageFeedbackVisual": {"DAMAGE_FLASH_COLOR": "INVALID_RED", "DAMAGE_FLASH_CORE_COLOR": "WARNING_ORANGE", "DEATH_FLASH_COLOR": "WARNING_ORANGE", "FLOAT_NUMBER_COLOR_DAMAGE": "INVALID_RED", "KILL_NOTIFY_COLOR": "INVALID_RED", "RESULT_SUMMARY_TEXT_COLOR": "NEUTRAL_UI_PALE_WHITE"},
}
var bad = []
for script_name in expect:
	var cm = load("res://scripts/%s.gd" % script_name).get_script_constant_map()
	for k in expect[script_name]:
		var got = UIConstants.slot_name(cm.get(k, Color(0, 0, 0, 0)))
		if got != expect[script_name][k]:
			bad.append("%s.%s=%s" % [script_name, k, got])
return ", ".join(bad)

var names = ["MovementRangeVisual", "EngagementRangeVisual", "CoherencyCircleVisual", "ChargeTrajectoryPreview", "DeepStrikeExclusionVisual", "DamageFeedbackVisual", "ChargeArrowVisual", "DeploymentZoneVisual", "AIMovementPathVisual", "HumanMovementPathVisual", "InfiltratorExclusionVisual"]
var re = RegEx.new()
re.compile("Color\\(|\\bColor\\.[A-Z]")
var hits = []
for n in names:
	var lines = FileAccess.get_file_as_string("res://scripts/%s.gd" % n).split("\n")
	for i in range(lines.size()):
		if re.search(lines[i]) != null:
			hits.append("%s:%d" % [n, i + 1])
return "%d hits %s" % [hits.size(), str(hits)]

var dfb = tree.root.get_node("Main/BoardRoot/DamageFeedbackVisual")
var got = {}
for c in dfb.get_children():
	if c is Label:
		got[c.text] = c.get_theme_color("font_color")
	elif c is ColorRect:
		got["bg%d" % c.z_index + "_" + str(snappedf(c.color.a, 0.01))] = c.color
var bad = []
var want = {"-3": UIConstants.INVALID_RED, "-2": UIConstants.INVALID_RED.darkened(0.2), "DESTROYED: Custodian Guard": UIConstants.INVALID_RED, "2 hits, 1 wound": UIConstants.NEUTRAL_UI_PALE_WHITE}
for k in want:
	if not got.has(k) or not got[k].is_equal_approx(want[k]):
		bad.append("%s=%s" % [k, str(got.get(k, "missing"))])
var shadows = 0
for k in got:
	var opaque = got[k]
	opaque.a = 1.0
	if k.begins_with("bg") and UIConstants.chrome_name(opaque) == "OVERLAY_SHADOW":
		shadows += 1
return "%s | shadow backdrops %d" % [", ".join(bad), shadows]

var img = Image.load_from_file(ProjectSettings.globalize_path("user://test_results/scenarios/T12_color_audit_T12_effects_reserves.png"))
if img == null:
	return "no capture"
var m = tree.root.get_node("Main")
var zoom = 1.0
var offset = Vector2(640, 1930) - Vector2(930, 575)
var out = []
for pair in [["ArrowFail", "INVALID_RED"], ["ArrowDeclared", "WARNING_ORANGE"]]:
	var a = m.get_node("BoardRoot/T12Probe/" + pair[0])
	var dir = (a.to_pos - a.from_pos).normalized()
	var centroid = a.to_pos - dir * cos(a.ARROW_HEAD_ANGLE) * a.ARROW_HEAD_SIZE * 2.0 / 3.0
	var sp = (centroid - offset) * zoom
	var c = img.get_pixel(int(sp.x), int(sp.y))
	var want = UIConstants.all_slots()[pair[1]]
	var ok = absf(c.r - want.r) < 0.02 and absf(c.g - want.g) < 0.02 and absf(c.b - want.b) < 0.02
	out.append("%s=%s" % [pair[0], pair[1] if ok else "#" + c.to_html(false)])
return ", ".join(out)

var img = Image.load_from_file(ProjectSettings.globalize_path("user://test_results/scenarios/T12_color_audit_T12_engagement_after.png"))
if img == null:
	return "no capture"
var m = tree.root.get_node("Main")
var dr = m.get_node("BoardRoot/T12Probe/DragRuler")
var zoom = 2.0
var offset = Vector2(380, 200) - Vector2(930, 575) / 2.0
var out = []
for seg in dr.segments:
	var mid = (seg.from + seg.to) / 2.0
	var sp = (mid - offset) * zoom
	var c = img.get_pixel(int(sp.x), int(sp.y))
	var want = UIConstants.all_slots()[seg.color_slot]
	var ok = absf(c.r - want.r) < 0.02 and absf(c.g - want.g) < 0.02 and absf(c.b - want.b) < 0.02
	out.append(seg.color_slot if ok else "#" + c.to_html(false))
return ", ".join(out)
